// The language index for Steam's language name (0, English, when not known).
inline unsigned languageIndex(const char* steam){if(steam)for(unsigned i=0;i<15;++i)if(!std::strcmp(steam,languages[i]))return i;return 0;}
inline const Name* find(uint32_t item){for(const auto& n:names)if(n.item==item)return &n;return nullptr;}
